         }
     }));
     sm.action({ jobParams: { owner: 'a', repo: 'b', machineAuthor: 'ai-teammate',
         validationConcurrency: 2, rules: [RULES.validate] } });

     assert.ok(dispatched(sm.capturedCliCommands),
