            // global arming form (validate-armed) widens; the
            // exclude-self recovery twins keep their own limits.
            if (!q.mutexExcludeSelf && typeof rule.limit === 'number') {
                patched.limit = Math.max(rule.limit, validationMutexMax);
            }
