// gh-837: one definition of "counts toward the approved merge window" —
// non-draft, not human-blocked, carrying pr_approved. Shared by the
// watermark probe (approvedQueueDepth) and the AC2 cost report so the
// three call sites cannot drift apart on blocked/draft semantics.
function approvedPrs(list) {
    return (list || []).filter(function (p) {
        if (!p || p.draft) return false;
        var labels = (p.labels || []).map(function (l) { return (l && l.name) || l; });
        return labels.indexOf('blocked') === -1 && labels.indexOf('pr_approved') !== -1;
    });
}
